/* My Ihsan 0.29.0: Kisah 25 Nabi, adult version (longer stories, Quran references, lessons) and the wives of the Prophet ﷺ.
   art: the scene drawn behind each story; objects and landscapes only, never a figure of a prophet or any person.
   Written from memory, following the Quran first: needs ustaz review before release. */
window.NABI_ADULT = [
{n:"Adam", art:"tree", sky:["#1d4d3a","#0d2a1e"],
 ms:["Allah memberitahu para malaikat bahawa Dia akan menjadikan seorang khalifah di bumi. Adam dicipta daripada tanah, lalu Allah meniupkan roh ke dalamnya dan mengajarkannya nama segala benda, ilmu yang tidak diketahui oleh para malaikat.","Para malaikat diperintah sujud hormat kepada Adam dan mereka semua sujud kecuali Iblis, yang sombong kerana merasa dirinya dicipta daripada api. Adam dan isterinya Hawa tinggal di syurga dan bebas menikmatinya, kecuali satu pokok yang dilarang.","Syaitan membisikkan bahawa pokok itu membawa kekekalan. Mereka tergelincir lalu memakannya. Berbeza dengan Iblis, mereka segera mengaku salah dan memohon ampun dengan kalimah \"Rabbana zalamna anfusana\", dan Allah menerima taubat mereka.","Mereka diturunkan ke bumi sebagai permulaan manusia. Di bumi, dua anak Adam mempersembahkan korban; Qabil yang dengki membunuh Habil, lalu belajar daripada seekor burung gagak cara mengebumikan saudaranya."],
 en:["Allah told the angels He would place a vicegerent on earth. Adam was created from clay, given a soul, and taught the names of all things, knowledge the angels did not have.","The angels were commanded to bow in respect to Adam, and all did except Iblis, who was proud because he was made of fire. Adam and his wife Hawa lived in Paradise, free to enjoy it except for one forbidden tree.","Satan whispered that the tree would give them eternity. They slipped and ate from it. Unlike Iblis, they admitted their wrong at once and prayed \"Rabbana zalamna anfusana\", and Allah accepted their repentance.","They were sent down to earth as the beginning of humankind. There, two of Adam's sons offered sacrifices; the envious Qabil killed Habil, then learned from a crow how to bury his brother."],
 l_ms:"Kesilapan bukan pengakhiran jika diikuti taubat; sombong dan dengki pula membawa kepada kebinasaan.", l_en:"A mistake is not the end if repentance follows; pride and envy lead to ruin.", q:"2:30-37; 7:11-25; 5:27-31; 38:71-76"},
{n:"Idris", art:"scroll", sky:["#2c3a5a","#121a2c"],
 ms:["Al-Quran menyebut Nabi Idris sebagai seorang yang sangat benar (siddiq) dan seorang nabi, dan Allah mengangkatnya ke tempat yang tinggi. Baginda juga disebut bersama Ismail dan Zulkifli sebagai orang-orang yang sabar.","Menurut sebahagian riwayat dan ahli sejarah, baginda hidup selepas Adam dan Syith, dan antara yang terawal menulis dengan pena serta mengajar ilmu kepada manusia. Riwayat-riwayat ini tidak semuanya kuat, maka yang pasti ialah pujian al-Quran kepadanya.","Dalam peristiwa Mikraj, Rasulullah ﷺ bertemu Nabi Idris di langit keempat, dan baginda menyambut Rasulullah ﷺ dengan ucapan \"selamat datang, saudara yang soleh dan nabi yang soleh\"."],
 en:["The Quran calls Idris a man of truth (siddiq) and a prophet, whom Allah raised to a high station. He is also named with Ismail and Dhul-Kifl among the patient.","According to some reports and historians he lived after Adam and Seth, and was among the first to write with a pen and teach people knowledge. Not all of these reports are strong; what is certain is the Quran's praise of him.","On the night of the Mi'raj, the Prophet ﷺ met Idris in the fourth heaven, and he welcomed him: \"Welcome, righteous brother and righteous prophet.\""],
 l_ms:"Kejujuran dan kesabaran mengangkat darjat seseorang di sisi Allah.", l_en:"Truthfulness and patience raise a person's rank with Allah.", q:"19:56-57; 21:85-86", h:"Sahih al-Bukhari 3207; Sahih Muslim 162"},
{n:"Nuh", art:"ark", sky:["#22384a","#0b1620"],
 ms:["Selepas manusia mula menyembah berhala yang dinamakan Wadd, Suwa', Yaghuth, Ya'uq dan Nasr, Allah mengutus Nuh. Baginda berdakwah siang dan malam, secara terang dan rahsia, selama 950 tahun.","Kaumnya menutup telinga dengan jari, menyelubungi diri dengan pakaian dan mengejek pengikutnya yang miskin. Hanya sedikit yang beriman. Allah memerintahkan Nuh membina bahtera; setiap kali pembesar kaum lalu, mereka mentertawakannya.","Apabila air memancar dari bumi dan turun dari langit, Nuh membawa orang beriman serta sepasang daripada setiap haiwan. Anaknya sendiri enggan naik dan berkata akan berlindung di gunung, lalu tenggelam. Isterinya juga tidak beriman.","Akhirnya bahtera berlabuh di Bukit Judi. Nuh berdoa memohon keampunan untuk dirinya, ibu bapanya dan semua orang beriman."],
 en:["When people began to worship idols named Wadd, Suwa', Yaghuth, Ya'uq and Nasr, Allah sent Nuh. He called them day and night, openly and in private, for 950 years.","His people put their fingers in their ears, covered themselves with their garments, and mocked his poor followers. Few believed. Allah told Nuh to build the ark; whenever the chiefs passed by, they laughed at him.","When water gushed from the earth and poured from the sky, Nuh took the believers and a pair of every animal. His own son refused to board, saying he would shelter on a mountain, and drowned. His wife, too, did not believe.","At last the ark came to rest on Mount Judi. Nuh prayed for forgiveness for himself, his parents and all the believers."],
 l_ms:"Hidayah milik Allah, bukan keturunan. Tugas kita ialah terus menyeru dengan sabar.", l_en:"Guidance belongs to Allah, not to family ties. Our task is to keep calling with patience.", q:"71:1-28; 11:25-49; 29:14; 66:10"},
{n:"Hud", art:"wind", sky:["#5a3a1a","#24160a"],
 ms:["Kaum 'Ad tinggal di al-Ahqaf, bukit-bukit pasir di selatan Semenanjung Arab. Mereka gagah dan membina kota Iram yang bertiang tinggi, yang tiada tandingannya ketika itu.","Nabi Hud, saudara mereka sendiri, mengajak mereka menyembah Allah dan memohon ampun supaya hujan dan kekuatan mereka ditambah. Mereka menjawab dengan sombong, \"Siapakah yang lebih kuat daripada kami?\"","Kemarau melanda. Apabila mereka melihat awan tebal menuju lembah mereka, mereka bergembira menyangka hujan. Sebenarnya itulah azab: angin yang sangat sejuk dan kencang selama tujuh malam lapan hari, hingga mereka bergelimpangan seperti batang kurma yang kosong.","Nabi Hud dan orang-orang beriman diselamatkan dengan rahmat Allah."],
 en:["The people of 'Ad lived in al-Ahqaf, the sand hills of southern Arabia. They were mighty, and built Iram of the lofty pillars, unmatched in its time.","Hud, one of their own, called them to worship Allah and seek forgiveness so their rain and strength would increase. They answered proudly, \"Who is stronger than us?\"","Drought came. When they saw a thick cloud heading for their valleys, they rejoiced, thinking it was rain. It was the punishment: a freezing, roaring wind for seven nights and eight days, leaving them strewn like hollow palm trunks.","Hud and the believers were saved by Allah's mercy."],
 l_ms:"Kekuatan dan kemajuan tanpa iman tidak dapat menyelamatkan sesiapa.", l_en:"Strength and progress without faith save no one.", q:"7:65-72; 11:50-60; 41:15-16; 46:21-25; 69:6-8; 89:6-8"},
{n:"Saleh", art:"camel", sky:["#6a3f2a","#2a1610"],
 ms:["Kaum Thamud mewarisi bumi selepas 'Ad. Mereka memahat rumah yang indah di gunung-ganang batu di al-Hijr. Nabi Saleh menyeru mereka kepada tauhid, tetapi mereka menuntut mukjizat.","Allah mengeluarkan seekor unta betina sebagai tanda. Air telaga dibahagikan: satu hari untuk unta, satu hari untuk mereka. Unta itu tidak boleh diganggu.","Sembilan orang perosak merancang kejahatan. Orang yang paling celaka antara mereka menyembelih unta itu. Nabi Saleh memberi tempoh tiga hari, kemudian datang suara yang dahsyat dan gegaran, lalu mereka mati bergelimpangan di rumah mereka.","Ketika melalui al-Hijr dalam perjalanan ke Tabuk, Rasulullah ﷺ menyuruh para sahabat mempercepatkan langkah dan tidak menggunakan air telaga mereka, sebagai peringatan."],
 en:["The Thamud inherited the land after 'Ad. They carved fine houses into the rock mountains of al-Hijr. Saleh called them to worship Allah alone, but they demanded a miracle.","Allah brought forth a she-camel as a sign. The well water was shared: one day for the camel, one day for them. The camel was not to be harmed.","Nine mischief-makers plotted, and the most wretched of them hamstrung the camel. Saleh gave them three days; then a mighty blast and tremor came, and they lay dead in their homes.","Passing al-Hijr on the way to Tabuk, the Prophet ﷺ told the companions to hurry through and not use its wells, as a reminder."],
 l_ms:"Meminta tanda tetapi kemudian menolaknya ialah tanda hati yang keras.", l_en:"Asking for a sign and then rejecting it shows a hardened heart.", q:"7:73-79; 11:61-68; 26:141-159; 27:45-53; 91:11-15", h:"Sahih al-Bukhari 3378-3381"},
{n:"Ibrahim", art:"fire", sky:["#5a2a10","#200d05"],
 ms:["Sejak muda Ibrahim berfikir tentang bintang, bulan dan matahari yang terbenam, lalu berkata bahawa dia tidak suka kepada yang tenggelam, dan menghadap kepada Pencipta langit dan bumi. Bapanya Azar ialah pembuat berhala.","Baginda memecahkan berhala-berhala ketika kaumnya keluar, dan meninggalkan yang paling besar. Apabila ditanya, baginda menyuruh mereka bertanya kepada berhala itu. Mereka murka lalu melemparkannya ke dalam api yang besar, dan Allah berfirman, \"Wahai api, jadilah sejuk dan selamat bagi Ibrahim.\"","Baginda berhijrah, kemudian meninggalkan Hajar dan bayi Ismail di lembah Makkah dengan perintah Allah. Bertahun-tahun kemudian baginda bermimpi menyembelih Ismail; kedua-duanya berserah, dan Allah menebusnya dengan seekor kibas. Bersama Ismail, baginda membina Kaabah sambil berdoa, \"Wahai Tuhan kami, terimalah daripada kami.\"","Baginda digelar Khalilullah, kekasih Allah, dan diuji dengan pelbagai perintah yang semuanya baginda sempurnakan."],
 en:["As a young man Ibrahim reflected on the setting star, moon and sun, declared he did not love things that set, and turned to the Creator of the heavens and earth. His father Azar made idols.","He broke the idols while his people were out, leaving the biggest one. When questioned, he told them to ask that idol. Enraged, they threw him into a great fire, and Allah said, \"O fire, be coolness and safety for Ibrahim.\"","He emigrated, and later left Hajar and the baby Ismail in the valley of Makkah at Allah's command. Years later he dreamed of sacrificing Ismail; both submitted, and Allah ransomed him with a ram. With Ismail he built the Kaabah, praying, \"Our Lord, accept this from us.\"","He is called Khalilullah, the friend of Allah, and was tested with commands which he fulfilled completely."],
 l_ms:"Yakin kepada Allah menjadikan api sejuk dan lembah kering diberkati.", l_en:"Certainty in Allah turned fire cool and a barren valley blessed.", q:"6:74-83; 21:51-73; 37:83-113; 14:35-41; 2:124-131"},
{n:"Lut", art:"stones", sky:["#3a2a3a","#140c14"],
 ms:["Lut ialah anak saudara Nabi Ibrahim yang beriman dan berhijrah bersamanya. Baginda diutus ke kota Sodom yang penduduknya melakukan perbuatan keji yang belum pernah dilakukan oleh mana-mana kaum sebelumnya, serta merompak di jalanan.","Para malaikat datang dalam rupa tetamu lelaki. Kaumnya bergegas datang untuk melakukan kejahatan, dan Lut merasa sangat susah hati. Para malaikat memberitahu bahawa mereka utusan Allah dan menyuruh Lut keluar bersama keluarganya pada waktu malam tanpa menoleh.","Isterinya tertinggal bersama orang yang dibinasakan. Pada waktu subuh, kota itu diterbalikkan dan dihujani batu daripada tanah yang dibakar."],
 en:["Lut was Ibrahim's nephew, who believed and emigrated with him. He was sent to Sodom, whose people committed an indecency no nation had done before, and robbed travellers on the roads.","Angels came in the form of male guests. His people rushed to commit evil, and Lut was greatly distressed. The angels revealed they were Allah's messengers and told him to leave with his family by night without looking back.","His wife stayed behind with those destroyed. At dawn the town was turned upside down and showered with stones of baked clay."],
 l_ms:"Berani menegur kemungkaran walaupun bersendirian.", l_en:"Have the courage to oppose wrong even when alone.", q:"7:80-84; 11:77-83; 15:57-77; 29:26-35"},
{n:"Ismail", art:"well", sky:["#4a3a1a","#1c1608"],
 ms:["Ismail ditinggalkan bersama ibunya Hajar di lembah Makkah yang tiada air dan tumbuhan. Apabila bekalan habis, Hajar berlari antara bukit Safa dan Marwah tujuh kali mencari air, dan Allah memancarkan air Zamzam.","Kabilah Jurhum kemudian menetap di situ, dan Ismail membesar bersama mereka serta mempelajari bahasa Arab. Apabila bapanya bermimpi menyembelihnya, Ismail berkata, \"Wahai ayahku, lakukanlah apa yang diperintahkan; insya-Allah engkau akan dapati aku dalam kalangan orang yang sabar.\"","Baginda membantu bapanya mengangkat batu Kaabah. Al-Quran memujinya sebagai seorang yang benar janjinya, yang menyuruh keluarganya bersolat dan berzakat. Daripada keturunannyalah lahir Nabi Muhammad ﷺ."],
 en:["Ismail was left with his mother Hajar in the valley of Makkah, with no water or plants. When supplies ran out, Hajar ran between Safa and Marwah seven times seeking water, and Allah brought forth the spring of Zamzam.","The tribe of Jurhum later settled there, and Ismail grew up with them and learned Arabic. When his father dreamed of sacrificing him, Ismail said, \"O my father, do as you are commanded; you will find me, if Allah wills, among the patient.\"","He helped his father raise the stones of the Kaabah. The Quran praises him as true to his promise, one who enjoined prayer and zakat on his family. From his line came the Prophet Muhammad ﷺ."],
 l_ms:"Pengorbanan dan ketaatan sebuah keluarga menjadi ibadah sehingga hari ini: sa'ie, Zamzam dan korban.", l_en:"A family's sacrifice and obedience became worship to this day: sa'i, Zamzam and the sacrifice.", q:"14:37; 37:100-111; 2:127-129; 19:54-55", h:"Sahih al-Bukhari 3364"},
{n:"Ishaq", art:"tent", sky:["#1c2a4a","#0a0f1e"],
 ms:["Para malaikat yang dalam perjalanan ke kaum Lut singgah sebagai tetamu Nabi Ibrahim, yang segera menghidangkan anak lembu panggang. Mereka membawa berita gembira: Sarah, isteri Ibrahim yang sudah tua dan mandul, akan melahirkan Ishaq, dan selepasnya Yaakub.","Sarah tertawa dan hairan, \"Bagaimanakah aku akan melahirkan sedangkan aku sudah tua dan suamiku juga tua?\" Para malaikat menjawab bahawa itu urusan Allah, dan rahmat serta berkat-Nya ke atas keluarga itu.","Ishaq menjadi nabi yang soleh, dan daripada keturunannya lahir ramai nabi Bani Israil."],
 en:["Angels on their way to Lut's people stopped as guests of Ibrahim, who hurried to serve them a roasted calf. They brought good news: Sarah, his elderly and barren wife, would bear Ishaq, and after him Yaqub.","Sarah laughed in wonder: \"How shall I bear a child when I am old and my husband is old?\" The angels replied that it was Allah's decree, and His mercy and blessings were upon that household.","Ishaq became a righteous prophet, and from his line came many prophets of the Children of Israel."],
 l_ms:"Tiada yang mustahil bagi Allah; jangan berputus asa daripada rahmat-Nya.", l_en:"Nothing is impossible for Allah; never despair of His mercy.", q:"11:69-73; 51:24-30; 37:112-113"},
{n:"Yaakub", art:"lamp", sky:["#2a2a44","#0e0e1a"],
 ms:["Yaakub, juga dikenali sebagai Israil, mempunyai dua belas orang anak lelaki. Baginda sangat menyayangi Yusuf dan adiknya Binyamin, dan ini menimbulkan dengki dalam hati abang-abang mereka.","Apabila mereka pulang membawa baju Yusuf yang berlumuran darah palsu, Yaakub tahu mereka berbohong dan berkata, \"Kesabaran yang indah,\" lalu memohon pertolongan Allah. Baginda menangis bertahun-tahun hingga matanya menjadi putih, tetapi tidak pernah berputus asa: \"Aku hanya mengadu kesusahan dan kesedihanku kepada Allah.\"","Akhirnya baju Yusuf diletakkan di wajahnya dan penglihatannya kembali. Sebelum wafat, baginda bertanya kepada anak-anaknya, \"Apakah yang kamu sembah selepasku?\" Mereka menjawab, \"Kami menyembah Tuhanmu dan Tuhan nenek moyangmu.\""],
 en:["Yaqub, also called Israel, had twelve sons. He loved Yusuf and his younger brother Binyamin dearly, which kindled envy in their older brothers.","When they returned with Yusuf's shirt stained with false blood, Yaqub knew they were lying and said, \"Beautiful patience,\" seeking Allah's help. He wept for years until his eyes turned white, yet never despaired: \"I only complain of my grief and sorrow to Allah.\"","At last Yusuf's shirt was laid on his face and his sight returned. Before he died he asked his sons, \"What will you worship after me?\" They said, \"We will worship your God and the God of your fathers.\""],
 l_ms:"Sabar yang indah ialah mengadu hanya kepada Allah dan tidak berputus asa.", l_en:"Beautiful patience means complaining only to Allah and never despairing.", q:"12:4-18, 83-101; 2:132-133"},
{n:"Yusuf", art:"shirts", sky:["#3a2a10","#140e04"],
 ms:["Ketika kecil, Yusuf bermimpi sebelas bintang, matahari dan bulan sujud kepadanya. Abang-abangnya yang dengki mencampakkannya ke dalam perigi dan membawa pulang bajunya yang dilumur darah palsu: baju pertama, tanda pembohongan.","Baginda dijual sebagai hamba di Mesir dan dibesarkan di rumah al-Aziz. Isteri al-Aziz cuba menggodanya, tetapi Yusuf lari ke pintu dan bajunya terkoyak dari belakang: baju kedua, bukti kesuciannya. Namun baginda tetap dipenjarakan, dan di penjara baginda berdakwah serta mentakbir mimpi.","Raja bermimpi tujuh ekor lembu gemuk dimakan tujuh ekor yang kurus. Yusuf mentakbirnya sebagai tujuh tahun subur diikuti tujuh tahun kemarau, lalu dilantik menjaga perbendaharaan. Abang-abangnya datang meminta makanan tanpa mengenalinya.","Apabila mereka akhirnya tahu, Yusuf memaafkan mereka: \"Tiada cercaan ke atas kamu pada hari ini.\" Baginda menghantar bajunya: baju ketiga, yang mengembalikan penglihatan ayahnya. Seluruh keluarga datang ke Mesir dan mimpi baginda menjadi kenyataan."],
 en:["As a boy, Yusuf dreamed that eleven stars, the sun and the moon bowed to him. His envious brothers threw him into a well and brought home his shirt stained with false blood: the first shirt, a sign of a lie.","He was sold as a slave in Egypt and raised in the house of al-Aziz. The wife of al-Aziz tried to seduce him, but Yusuf ran to the door and his shirt was torn from behind: the second shirt, proof of his innocence. Still he was imprisoned, and in prison he called to Allah and interpreted dreams.","The king dreamed of seven fat cows eaten by seven lean ones. Yusuf explained it as seven fertile years followed by seven of drought, and was put in charge of the storehouses. His brothers came for food without recognising him.","When they finally knew, Yusuf forgave them: \"No blame upon you today.\" He sent his shirt: the third shirt, which restored his father's sight. The whole family came to Egypt and his dream came true."],
 l_ms:"Kesucian diri, sabar dan memaafkan membawa kepada kemuliaan, walaupun melalui perigi dan penjara.", l_en:"Chastity, patience and forgiveness lead to honour, even by way of a well and a prison.", q:"12:1-111"},
{n:"Ayyub", art:"spring", sky:["#1a3a3a","#081818"],
 ms:["Ayyub seorang nabi yang dikurniakan harta, anak-anak dan kesihatan. Allah mengujinya dengan kehilangan semuanya dan penyakit yang berpanjangan selama bertahun-tahun, sehingga ramai orang menjauhinya.","Baginda tetap sabar dan tidak pernah merungut. Doanya penuh adab: \"Sesungguhnya aku ditimpa kesusahan, dan Engkaulah Yang Paling Penyayang antara semua yang penyayang.\"","Allah memerintahkannya menghentakkan kaki ke bumi, lalu memancarlah air yang sejuk untuk mandi dan minum, dan baginda sembuh. Allah mengembalikan keluarganya dan melipatgandakannya. Al-Quran memujinya: \"Sebaik-baik hamba; sesungguhnya dia sentiasa kembali kepada Allah.\""],
 en:["Ayyub was a prophet blessed with wealth, children and health. Allah tested him with the loss of everything and a long illness lasting years, until many people kept away from him.","He stayed patient and never complained. His prayer was full of courtesy: \"Adversity has touched me, and You are the Most Merciful of the merciful.\"","Allah told him to strike the ground with his foot, and cool water sprang up to bathe in and drink, and he was healed. Allah returned his family and doubled it. The Quran praises him: \"An excellent servant; he always turned back to Allah.\""],
 l_ms:"Ujian yang berat ialah jalan kepada kedudukan yang tinggi jika dihadapi dengan sabar.", l_en:"Heavy trials are a path to a high rank when met with patience.", q:"21:83-84; 38:41-44"},
{n:"Syuaib", art:"scales", sky:["#3a3a1a","#16160a"],
 ms:["Nabi Syuaib diutus kepada penduduk Madyan dan Aikah. Selain syirik, mereka terkenal menipu dalam sukatan dan timbangan, mengurangkan hak orang dan merosakkan bumi.","Baginda berhujah dengan lembut dan fasih, mengingatkan nikmat Allah dan nasib kaum-kaum terdahulu: \"Aku hanya mahu membuat kebaikan sedaya upayaku.\" Mereka mengejeknya dan mengancam untuk menghalaunya.","Azab datang kepada mereka dalam bentuk gegaran dan suara yang dahsyat, dan bagi penduduk Aikah, \"hari yang dinaungi awan\". Syuaib dan orang beriman diselamatkan."],
 en:["Shu'ayb was sent to the people of Madyan and Aykah. Besides idolatry, they were known for cheating in measures and weights, short-changing people and spreading corruption.","He reasoned with them gently and eloquently, reminding them of Allah's blessings and the fate of earlier nations: \"I only want to set things right as far as I can.\" They mocked him and threatened to drive him out.","The punishment came as a tremor and a mighty blast, and for the people of Aykah, \"the day of the overshadowing cloud\". Shu'ayb and the believers were saved."],
 l_ms:"Jujur dalam jual beli ialah sebahagian daripada iman.", l_en:"Honesty in trade is part of faith.", q:"7:85-93; 11:84-95; 26:176-191"},
{n:"Musa", art:"sea", sky:["#12304a","#06121e"],
 ms:["Musa lahir ketika Firaun membunuh bayi lelaki Bani Israil. Ibunya, dengan ilham Allah, menghanyutkannya di sungai Nil dalam peti, dan baginda dipungut oleh isteri Firaun lalu dikembalikan kepada ibunya untuk disusukan.","Setelah dewasa, baginda tidak sengaja membunuh seorang lelaki Mesir dan lari ke Madyan, bekerja menggembala kambing bertahun-tahun. Dalam perjalanan pulang, di lembah suci Tuwa, Allah berkata-kata kepadanya dan memberinya mukjizat: tongkat yang menjadi ular dan tangan yang bercahaya.","Bersama saudaranya Harun, baginda menyeru Firaun. Ahli-ahli sihir Firaun akhirnya beriman. Apabila Bani Israil dikejar, Allah membelah laut dengan pukulan tongkat Musa, dan Firaun tenggelam.","Baginda menerima Taurat di Bukit Tursina, menghadapi kaum yang menyembah anak lembu emas, dan belajar kerendahan hati daripada pertemuan dengan Khidir."],
 en:["Musa was born when Pharaoh was killing the baby boys of the Children of Israel. His mother, inspired by Allah, set him afloat on the Nile in a chest; Pharaoh's wife took him in and he was returned to his mother to be nursed.","As a man he accidentally killed an Egyptian and fled to Madyan, tending flocks for years. On the way back, in the sacred valley of Tuwa, Allah spoke to him and gave him signs: a staff that became a serpent and a shining hand.","With his brother Harun he called Pharaoh. Pharaoh's magicians ended up believing. When the Children of Israel were pursued, Allah parted the sea at the strike of Musa's staff, and Pharaoh drowned.","He received the Torah at Mount Sinai, faced a people who worshipped a golden calf, and learned humility through his journey with Khidr."],
 l_ms:"Allah melindungi orang yang bertawakal, dan ilmu menuntut sikap rendah hati.", l_en:"Allah protects those who rely on Him, and knowledge demands humility.", q:"28:3-46; 20:9-98; 26:10-68; 18:60-82; 10:90-92"},
{n:"Harun", art:"staff", sky:["#1e3a40","#0a1618"],
 ms:["Harun ialah abang Nabi Musa yang petah berbicara. Musa berdoa supaya Harun dijadikan pembantunya: \"Teguhkanlah kekuatanku dengannya dan jadikanlah dia sekutu dalam urusanku,\" dan Allah memperkenankannya.","Ketika Musa ke Bukit Tursina selama empat puluh malam, Harun memimpin Bani Israil. As-Samiri menyesatkan mereka dengan patung anak lembu emas; Harun menegur mereka tetapi mereka enggan mendengar sehingga Musa kembali.","Apabila Musa menarik janggut dan kepalanya kerana marah, Harun menjelaskan dengan lembut bahawa dia takut kaum itu berpecah-belah. Musa lalu berdoa memohon ampun untuk mereka berdua."],
 en:["Harun was Musa's eloquent elder brother. Musa prayed that Harun be made his helper: \"Strengthen me through him and let him share my task,\" and Allah granted it.","When Musa went to Mount Sinai for forty nights, Harun led the Children of Israel. As-Samiri misled them with a golden calf; Harun warned them but they would not listen until Musa returned.","When Musa, in anger, seized his beard and head, Harun gently explained he feared the people would split apart. Musa then prayed for forgiveness for them both."],
 l_ms:"Saling membantu dalam kebaikan dan menjaga perpaduan.", l_en:"Help one another in good and keep people united.", q:"20:29-36, 90-94; 28:34-35; 7:142-151"},
{n:"Zulkifli", art:"lamp2", sky:["#2a2a2a","#0f0f0f"],
 ms:["Al-Quran menyebut Zulkifli bersama Ismail dan Idris sebagai orang-orang yang sabar dan antara orang-orang yang terbaik. Ulama berbeza pendapat tentang siapa sebenarnya baginda.","Menurut sebahagian riwayat tafsir, baginda menyanggupi janji untuk berpuasa pada siang hari, bersolat pada malam hari dan menghakimi manusia tanpa marah, lalu baginda menunaikan janji itu, dan kerana itulah digelar Zulkifli (yang menunaikan tanggungan).","Riwayat terperinci ini tidak semuanya kukuh; yang pasti ialah pujian Allah terhadap kesabaran baginda."],
 en:["The Quran names Dhul-Kifl with Ismail and Idris among the patient and among the best. Scholars differ on exactly who he was.","According to some tafsir reports, he pledged to fast by day, pray by night and judge people without anger, and kept that pledge, which is why he was called Dhul-Kifl (the one who fulfilled his charge).","These detailed reports are not all firm; what is certain is Allah's praise of his patience."],
 l_ms:"Tunaikan janji dan kawal kemarahan.", l_en:"Keep your promises and control your anger.", q:"21:85-86; 38:48"},
{n:"Daud", art:"armour", sky:["#2a3a2a","#0e160e"],
 ms:["Ketika masih muda dalam tentera Talut, Daud membunuh Jalut, panglima yang gagah, dan Allah mengurniakannya kerajaan dan hikmah. Baginda diberi kitab Zabur.","Gunung-ganang dan burung-burung bertasbih bersamanya, dan Allah melembutkan besi di tangannya sehingga baginda membuat baju besi berlingkar. Rasulullah ﷺ bersabda bahawa Daud makan daripada hasil tangannya sendiri.","Puasa yang paling disukai Allah ialah puasa Daud: sehari berpuasa, sehari tidak; dan solat malam yang paling disukai ialah solatnya. Allah juga mengajarnya berhati-hati dalam menghakimi melalui kisah dua orang yang bertelagah."],
 en:["As a young soldier in Talut's army, Dawud killed Jalut, the mighty champion, and Allah gave him kingship and wisdom. He was given the Zabur.","The mountains and birds glorified Allah with him, and Allah softened iron in his hands so he made ringed coats of mail. The Prophet ﷺ said Dawud ate from the work of his own hands.","The fast most beloved to Allah is Dawud's: fasting one day and not the next; and the most beloved night prayer is his. Allah also taught him care in judgment through the case of two disputants."],
 l_ms:"Kuasa dan kekayaan tidak menghalang seseorang daripada bekerja, berpuasa dan beribadah.", l_en:"Power and wealth do not stop one from working, fasting and worshipping.", q:"2:251; 34:10-11; 38:17-26; 21:79-80", h:"Sahih al-Bukhari 1131, 2072"},
{n:"Sulaiman", art:"ants", sky:["#3a2a4a","#160e1c"],
 ms:["Sulaiman mewarisi Daud dan dianugerahkan kerajaan yang tiada tandingan: memahami bahasa burung dan semut, angin yang bertiup dengan perintahnya, dan jin yang bekerja untuknya.","Di lembah semut, seekor semut menyeru kawan-kawannya masuk ke sarang supaya tidak terpijak tanpa disedari. Sulaiman tersenyum dan bersyukur kepada Allah. Burung hud-hud membawa berita tentang Ratu Saba' yang menyembah matahari; baginda mengutus surat, dan singgahsana ratu itu dibawa dalam sekelip mata.","Ratu Saba' akhirnya berserah diri kepada Allah bersama Sulaiman. Baginda wafat dalam keadaan bersandar pada tongkat, dan jin tidak menyedarinya sehingga anai-anai memakan tongkat itu."],
 en:["Sulayman inherited Dawud and was given a kingdom like no other: understanding the speech of birds and ants, the wind blowing at his command, and jinn working for him.","In the valley of the ants, an ant called on the others to enter their homes so they would not be crushed unknowingly. Sulayman smiled and thanked Allah. The hoopoe brought news of the Queen of Saba' who worshipped the sun; he sent a letter, and her throne was brought in the blink of an eye.","The Queen of Saba' finally submitted to Allah with Sulayman. He died leaning on his staff, and the jinn did not realise it until termites ate through the staff."],
 l_ms:"Nikmat yang besar ialah ujian kesyukuran.", l_en:"Great blessings are a test of gratitude.", q:"27:15-44; 34:12-14; 38:30-40"},
{n:"Ilyas", art:"rain", sky:["#26303e","#0c1016"],
 ms:["Nabi Ilyas diutus kepada kaumnya yang menyembah berhala bernama Ba'l dan meninggalkan Allah, sebaik-baik Pencipta. Baginda menyeru, \"Tidakkah kamu bertakwa?\"","Kebanyakan kaumnya mendustakannya, kecuali hamba-hamba Allah yang ikhlas. Allah mengekalkan sebutan baik baginya dalam kalangan generasi kemudian: \"Salam sejahtera ke atas Ilyas.\""],
 en:["Ilyas was sent to his people, who worshipped an idol named Ba'l and abandoned Allah, the best of creators. He called out, \"Will you not be mindful of Allah?\"","Most of his people rejected him, except Allah's sincere servants. Allah kept his good name among later generations: \"Peace be upon Ilyas.\""],
 l_ms:"Jangan menggantikan Allah dengan apa-apa yang disanjung manusia.", l_en:"Never put anything people glorify in Allah's place.", q:"37:123-132; 6:85"},
{n:"Ilyasa'", art:"olive", sky:["#2a3a26","#0e140c"],
 ms:["Ilyasa' disebut dalam al-Quran dalam kalangan nabi yang dilebihkan atas sekalian alam dan dalam kalangan orang-orang terbaik. Menurut ahli sejarah, baginda meneruskan dakwah Nabi Ilyas kepada Bani Israil.","Al-Quran tidak memperincikan kisahnya; ia mengajar bahawa setiap nabi, walaupun sedikit kisahnya diketahui, membawa risalah yang sama."],
 en:["Al-Yasa' is named in the Quran among the prophets favoured above the worlds and among the best. According to historians he continued Ilyas's mission among the Children of Israel.","The Quran does not detail his story; it teaches that every prophet, even one whose story we know little of, carried the same message."],
 l_ms:"Nilai seseorang di sisi Allah tidak bergantung pada kemasyhurannya.", l_en:"A person's worth with Allah does not depend on fame.", q:"6:86; 38:48"},
{n:"Yunus", art:"whale", sky:["#0e2a3a","#041018"],
 ms:["Nabi Yunus diutus ke Ninawa. Apabila kaumnya enggan beriman, baginda pergi dalam keadaan marah sebelum diizinkan Allah, dan menaiki sebuah kapal yang sarat.","Undian dibuat untuk meringankan kapal dan Yunus terpilih, lalu dicampakkan ke laut dan ditelan ikan besar. Dalam tiga kegelapan, iaitu malam, laut dan perut ikan, baginda bertasbih: \"Tiada tuhan melainkan Engkau, Maha Suci Engkau, sesungguhnya aku termasuk orang yang zalim.\"","Allah menyelamatkannya; baginda dicampakkan ke pantai dalam keadaan sakit dan Allah menumbuhkan pokok labu untuk menaunginya. Kaumnya, seratus ribu orang atau lebih, akhirnya beriman, satu-satunya kaum yang diselamatkan setelah melihat tanda azab."],
 en:["Yunus was sent to Nineveh. When his people refused to believe, he left in anger before Allah permitted him and boarded a laden ship.","Lots were cast to lighten the ship and Yunus was chosen, thrown into the sea and swallowed by a great fish. In three darknesses, of night, sea and the fish's belly, he glorified Allah: \"There is no god but You, glory be to You; I have been among the wrongdoers.\"","Allah saved him; he was cast ashore sick and Allah grew a gourd plant to shade him. His people, a hundred thousand or more, finally believed, the only nation spared after seeing the signs of punishment."],
 l_ms:"Tiada kegelapan terlalu dalam untuk doa yang ikhlas.", l_en:"No darkness is too deep for a sincere prayer.", q:"21:87-88; 37:139-148; 10:98; 68:48-50"},
{n:"Zakaria", art:"mihrab", sky:["#3a2a1a","#160e06"],
 ms:["Zakaria menjaga Maryam di mihrab. Setiap kali masuk, baginda mendapati rezeki di sisinya. Apabila Maryam berkata rezeki itu dari Allah yang memberi tanpa hitungan, Zakaria terdorong untuk berdoa.","Walaupun sudah tua dan isterinya mandul, baginda berdoa dengan suara perlahan memohon zuriat yang akan mewarisi dakwahnya. Allah memberi khabar gembira tentang Yahya, dan tandanya ialah baginda tidak dapat berkata-kata selama tiga malam kecuali dengan isyarat, sambil bertasbih pagi dan petang."],
 en:["Zakariya was Maryam's guardian in the prayer niche. Whenever he entered, he found provision with her. When Maryam said it was from Allah, who provides without measure, Zakariya was moved to pray.","Though old and with a barren wife, he prayed softly for an heir to carry on the mission. Allah gave him good news of Yahya, and his sign was that he could not speak for three nights except by gestures, while glorifying Allah morning and evening."],
 l_ms:"Berdoalah walaupun sebab-sebab nampak tertutup; Allah Maha Berkuasa.", l_en:"Pray even when every means seems closed; Allah has power over all things.", q:"3:37-41; 19:2-11; 21:89-90"},
{n:"Yahya", art:"book", sky:["#2a3a3a","#0c1616"],
 ms:["Yahya dikurniakan hikmah sejak kecil dan diperintah memegang Kitab dengan teguh. Baginda bersifat belas kasihan, suci, bertakwa, berbakti kepada ibu bapa dan tidak sombong.","Baginda membenarkan kalimah daripada Allah, iaitu Nabi Isa, dan menjadi pemimpin serta orang yang menjaga diri. Allah berfirman: \"Salam sejahtera ke atasnya pada hari dia dilahirkan, pada hari dia wafat dan pada hari dia dibangkitkan hidup semula.\""],
 en:["Yahya was given wisdom as a child and commanded to hold the Book firmly. He was compassionate, pure, God-fearing, dutiful to his parents and never arrogant.","He confirmed a word from Allah, that is the Prophet Isa, and was a leader and chaste. Allah says: \"Peace be upon him the day he was born, the day he dies and the day he is raised alive.\""],
 l_ms:"Berbakti kepada ibu bapa dan rendah hati ialah tanda ilmu yang benar.", l_en:"Kindness to parents and humility are signs of true knowledge.", q:"19:12-15; 3:39"},
{n:"Isa", art:"table", sky:["#2a3450","#0c1020"],
 ms:["Maryam, wanita suci yang dipilih Allah, mengandungkan Isa tanpa bapa. Ketika sakit bersalin di bawah pohon kurma, dia diseru supaya menggoncang pohon itu untuk mendapat buah kurma yang masak dan minum dari anak sungai. Bayi Isa berkata-kata dari buaian: \"Aku hamba Allah; Dia memberiku Kitab dan menjadikan aku nabi.\"","Dengan izin Allah, baginda membentuk burung daripada tanah lalu ia menjadi burung, menyembuhkan orang buta dan sopak, serta menghidupkan orang mati. Baginda diberi Injil dan diikuti oleh Hawariyyun. Atas permintaan mereka, Allah menurunkan hidangan dari langit.","Mereka tidak membunuh dan tidak menyalibnya; Allah mengangkatnya. Rasulullah ﷺ bersabda bahawa Isa akan turun semula sebelum Kiamat."],
 en:["Maryam, a pure woman chosen by Allah, conceived Isa without a father. In labour under a palm tree, she was told to shake its trunk for ripe dates and drink from a stream below. The baby Isa spoke from the cradle: \"I am the servant of Allah; He has given me the Book and made me a prophet.\"","By Allah's permission he shaped a bird from clay and it became a bird, healed the blind and the leper, and brought the dead to life. He was given the Injil and followed by the disciples. At their request Allah sent down a table spread from heaven.","They did not kill him nor crucify him; Allah raised him up. The Prophet ﷺ said Isa will descend again before the Hour."],
 l_ms:"Mukjizat datang dengan izin Allah; nabi ialah hamba Allah, bukan tuhan.", l_en:"Miracles come by Allah's permission; a prophet is Allah's servant, not a god.", q:"19:16-36; 3:45-55; 5:110-118; 4:157-158", h:"Sahih al-Bukhari 3448"},
{n:"Muhammad ﷺ", art:"kaabah", sky:["#1a3a2a","#06140c"],
 ms:["Baginda lahir di Makkah pada Tahun Gajah sebagai anak yatim, disusukan oleh Halimah dan membesar dengan gelaran al-Amin, yang dipercayai. Baginda berkahwin dengan Khadijah dan sering beruzlah di Gua Hira'. Pada usia 40 tahun, Jibril datang membawa wahyu pertama: \"Bacalah dengan nama Tuhanmu yang menciptakan.\"","Selama 13 tahun di Makkah baginda berdakwah dalam penindasan; para sahabat diseksa, baginda dihalau di Taif, dan dimuliakan dengan Isra' dan Mikraj. Baginda berhijrah ke Madinah melalui Gua Thur, membina masjid dan mempersaudarakan Muhajirin dengan Ansar.","Melalui Badar, Uhud, Khandak dan Perjanjian Hudaibiyah, Islam berkembang. Pada pembukaan Makkah, baginda memaafkan penduduk yang pernah memusuhinya. Selepas Haji Wida', baginda wafat pada tahun 11 Hijrah dalam usia 63 tahun.","Baginda ialah penutup segala nabi dan rahmat bagi seluruh alam. Kisah penuh baginda ada dalam Garis masa Sirah."],
 en:["He was born in Makkah in the Year of the Elephant, an orphan, nursed by Halimah, and grew up known as al-Amin, the trustworthy. He married Khadijah and often retreated to the cave of Hira'. At forty, Jibril brought the first revelation: \"Read in the name of your Lord who created.\"","For 13 years in Makkah he called people under persecution; his companions were tortured, he was driven out of Taif, and he was honoured with the Isra' and Mi'raj. He emigrated to Madinah by way of the cave of Thawr, built the mosque and joined the Emigrants and Helpers in brotherhood.","Through Badr, Uhud, the Trench and the Treaty of Hudaybiyyah, Islam grew. At the opening of Makkah he forgave the people who had fought him. After the Farewell Pilgrimage he passed away in 11 AH at the age of 63.","He is the seal of the prophets and a mercy to all the worlds. His full story is in the Sirah timeline."],
 l_ms:"Akhlak yang mulia, kesabaran dan sifat pemaaf ialah teras dakwah.", l_en:"Noble character, patience and forgiveness are at the heart of calling to Allah.", q:"96:1-5; 17:1; 9:40; 33:40; 21:107; 68:4"}
];

window.ISTERI_NABI = [
{n:"Khadijah binti Khuwailid", t_ms:"Isteri pertama, ibu kepada anak-anak baginda", t_en:"First wife, mother of his children", art:"hira",
 ms:"Saudagar wanita Quraisy yang mulia dan kaya. Beliau tertarik dengan kejujuran Muhammad ﷺ yang menguruskan dagangannya, lalu melamar baginda. Ketika wahyu pertama turun dan baginda pulang dalam ketakutan, Khadijah menenangkannya: \"Demi Allah, Allah tidak akan menghinamu, kerana engkau menyambung silaturahim, menanggung yang lemah dan membantu yang ditimpa musibah.\" Beliau orang pertama yang beriman dan menginfakkan hartanya untuk Islam. Beliau wafat tiga tahun sebelum Hijrah, dan baginda sentiasa mengenangnya. Jibril menyampaikan salam dari Allah kepadanya dengan khabar sebuah rumah di syurga.",
 en:"A noble and wealthy Quraysh merchant. Impressed by the honesty of Muhammad ﷺ in managing her trade, she proposed to him. When the first revelation came and he returned frightened, she comforted him: \"By Allah, Allah will never disgrace you, for you keep ties of kinship, carry the weak and help those struck by hardship.\" She was the first to believe and spent her wealth for Islam. She died three years before the Hijrah, and he never stopped remembering her. Jibril conveyed Allah's greeting to her with news of a house in Paradise.",
 src:"Sahih al-Bukhari 3, 3820; Sahih Muslim 2432"},
{n:"Saudah binti Zam'ah", t_ms:"Pendamping selepas Khadijah", t_en:"Companion after Khadijah", art:"date",
 ms:"Antara yang awal memeluk Islam dan berhijrah ke Habsyah bersama suami pertamanya, yang kemudian meninggal dunia. Baginda ﷺ mengahwininya selepas wafat Khadijah, ketika baginda memerlukan seseorang menjaga rumah dan anak-anak. Saudah terkenal pemurah, ceria dan suka membuat baginda tersenyum. Beliau memberikan gilirannya kepada Aisyah kerana mahu kekal sebagai isteri baginda di dunia dan akhirat.",
 en:"Among the early Muslims, she emigrated to Abyssinia with her first husband, who later died. The Prophet ﷺ married her after Khadijah's death, when he needed someone to care for his home and daughters. Saudah was known for her generosity and cheerfulness, often making him smile. She gave her turn to Aisha, wishing to remain his wife in this life and the next.",
 src:"Sahih al-Bukhari 2593, 5212; Sahih Muslim 1463"},
{n:"Aisyah binti Abu Bakar", t_ms:"Ulama wanita terbesar umat", t_en:"The greatest woman scholar of the ummah", art:"book",
 ms:"Puteri Abu Bakar as-Siddiq. Beliau sangat cerdas dan meriwayatkan lebih 2,000 hadis, menjadi rujukan para sahabat dalam fiqh, tafsir dan sirah. Allah menurunkan ayat-ayat Surah an-Nur untuk membersihkan namanya daripada fitnah. Baginda ﷺ wafat di rumahnya, dengan kepala baginda di pangkuannya. Selepas itu beliau mengajar umat selama berpuluh tahun.",
 en:"Daughter of Abu Bakr as-Siddiq. Highly intelligent, she narrated over 2,000 hadith and was the companions' reference in fiqh, tafsir and sirah. Allah revealed verses of Surah an-Nur to clear her name of slander. The Prophet ﷺ passed away in her home, his head resting on her lap. Afterwards she taught the ummah for decades.",
 src:"An-Nur 24:11-26; Sahih al-Bukhari 4141, 4450"},
{n:"Hafsah binti Umar", t_ms:"Penjaga mushaf al-Quran", t_en:"Keeper of the Quran manuscript", art:"scroll",
 ms:"Puteri Umar al-Khattab. Suaminya Khunais syahid selepas Badar, lalu baginda ﷺ mengahwininya. Beliau kuat berpuasa dan bersolat malam. Mushaf al-Quran yang dikumpul pada zaman Abu Bakar disimpan di rumahnya, dan daripada mushaf itulah Uthman menyalin mushaf-mushaf yang dihantar ke seluruh wilayah Islam.",
 en:"Daughter of Umar ibn al-Khattab. Her husband Khunays was martyred after Badr, and the Prophet ﷺ married her. She was devoted to fasting and night prayer. The Quran compiled in Abu Bakr's time was kept in her home, and from it Uthman copied the masters sent across the Muslim lands.",
 src:"Sahih al-Bukhari 4005, 4987"},
{n:"Zainab binti Khuzaimah", t_ms:"Ummul Masakin, ibu orang miskin", t_en:"Umm al-Masakin, mother of the poor", art:"bread",
 ms:"Beliau digelar Ummul Masakin kerana sangat pemurah kepada orang miskin sejak sebelum Islam. Suaminya syahid di Uhud, lalu baginda ﷺ mengahwininya. Beliau hanya hidup beberapa bulan sebagai isteri baginda dan wafat pada zaman baginda, dan baginda sendiri menyembahyangkannya.",
 en:"She was called Umm al-Masakin for her great generosity to the poor even before Islam. Her husband was martyred at Uhud, and the Prophet ﷺ married her. She lived only a few months as his wife and died in his lifetime; he led her funeral prayer himself.",
 src:"Ibn Sa'd, at-Tabaqat 8/115; al-Isabah (Ibn Hajar)"},
{n:"Ummu Salamah (Hind binti Abi Umayyah)", t_ms:"Bijaksana dan tenang", t_en:"Wise and calm", art:"tent",
 ms:"Antara yang awal berhijrah ke Habsyah dan ke Madinah, dipisahkan daripada suami dan anaknya selama setahun. Selepas suaminya Abu Salamah wafat, beliau membaca doa yang diajar baginda: \"Ya Allah, berilah aku pahala dalam musibahku dan gantikanlah dengan yang lebih baik,\" lalu Allah menggantikannya dengan Rasulullah ﷺ. Di Hudaibiyah, nasihatnya agar baginda bercukur dan menyembelih dahulu membuatkan para sahabat segera mengikut.",
 en:"Among the first to emigrate to Abyssinia and to Madinah, she was separated from her husband and son for a year. When her husband Abu Salamah died, she said the prayer he had taught: \"O Allah, reward me in my affliction and replace it with something better,\" and Allah replaced him with the Prophet ﷺ. At Hudaybiyyah, her advice that he shave and sacrifice first led the companions to follow at once.",
 src:"Sahih Muslim 918; Sahih al-Bukhari 2731-2732"},
{n:"Zainab binti Jahsy", t_ms:"Yang tangannya paling panjang dalam sedekah", t_en:"The one with the longest hand in charity", art:"needle",
 ms:"Sepupu baginda ﷺ. Perkahwinannya dengan baginda diperintahkan oleh Allah dalam Surah al-Ahzab, untuk membatalkan adat bahawa anak angkat sama seperti anak kandung. Beliau bekerja dengan tangannya sendiri, menyamak dan menjahit, lalu menyedekahkan hasilnya. Baginda bersabda isteri yang paling cepat menyusulnya ialah yang paling panjang tangannya, dan ternyata Zainab, kerana banyaknya sedekah.",
 en:"The Prophet's ﷺ cousin. Her marriage to him was commanded by Allah in Surah al-Ahzab, ending the custom that an adopted son is like a natural son. She worked with her own hands, tanning and sewing, and gave the earnings in charity. He said the wife who would join him first was the one with the longest hand, and it was Zainab, for her abundant giving.",
 src:"Al-Ahzab 33:37; Sahih Muslim 2452"},
{n:"Juwairiyah binti al-Harith", t_ms:"Paling berkat kepada kaumnya", t_en:"Most blessed for her people", art:"stars",
 ms:"Puteri ketua Bani Mustaliq yang ditawan selepas peperangan. Baginda ﷺ membebaskan dan mengahwininya, lalu para sahabat membebaskan ratusan tawanan kaumnya kerana mereka kini kerabat Rasulullah. Aisyah berkata tiada wanita yang lebih berkat kepada kaumnya daripada Juwairiyah. Baginda mengajarnya zikir \"Subhanallahi wa bihamdihi, 'adada khalqihi...\" yang lebih berat daripada zikir sepanjang pagi.",
 en:"Daughter of the chief of Banu Mustaliq, captured after battle. The Prophet ﷺ freed and married her, and the companions freed hundreds of her people since they were now his in-laws. Aisha said no woman was more blessed for her people than Juwayriyah. He taught her the dhikr \"Subhanallahi wa bihamdihi, 'adada khalqihi...\", weightier than a whole morning of dhikr.",
 src:"Sunan Abi Dawud 3931; Sahih Muslim 2726"},
{n:"Ummu Habibah (Ramlah binti Abi Sufyan)", t_ms:"Teguh walaupun berjauhan", t_en:"Steadfast though far away", art:"ship",
 ms:"Puteri Abu Sufyan, pemimpin Quraisy yang ketika itu memusuhi Islam. Beliau berhijrah ke Habsyah, dan di sana suaminya murtad, tetapi beliau tetap teguh. Baginda ﷺ melamarnya dari Madinah, dan Raja Najasyi mewakili akad nikahnya. Apabila bapanya datang ke Madinah sebelum memeluk Islam, beliau melipat tikar baginda kerana bapanya masih musyrik.",
 en:"Daughter of Abu Sufyan, the Quraysh leader then hostile to Islam. She emigrated to Abyssinia, where her husband left Islam, but she stayed firm. The Prophet ﷺ proposed to her from Madinah, and the Negus represented the marriage. When her father came to Madinah before accepting Islam, she folded away the Prophet's mat because her father was still an idolater.",
 src:"Sunan Abi Dawud 2107; Ibn Sa'd, at-Tabaqat 8/99"},
{n:"Safiyyah binti Huyay", t_ms:"Keturunan Nabi Harun", t_en:"Descendant of Prophet Harun", art:"date",
 ms:"Puteri ketua Bani Nadhir, berketurunan Nabi Harun. Selepas Khaibar beliau memeluk Islam, dibebaskan dan dikahwini oleh baginda ﷺ, dengan pembebasannya sebagai mahar. Apabila beliau diejek kerana keturunannya, baginda mengajarnya menjawab: \"Ayahku Harun, bapa saudaraku Musa, dan suamiku Muhammad.\"",
 en:"Daughter of the chief of Banu Nadir, descended from Prophet Harun. After Khaybar she embraced Islam and the Prophet ﷺ freed and married her, her freedom being her dowry. When she was teased about her ancestry, he taught her to answer: \"My father is Harun, my uncle is Musa, and my husband is Muhammad.\"",
 src:"Sahih al-Bukhari 371; Sunan at-Tirmidhi 3894"},
{n:"Maimunah binti al-Harith", t_ms:"Isteri terakhir yang dinikahi", t_en:"The last wife he married", art:"tree",
 ms:"Baginda ﷺ mengahwininya di Sarif berhampiran Makkah selepas Umrah Qadha' pada tahun 7 Hijrah. Beliau ibu saudara kepada Ibnu Abbas dan Khalid al-Walid, dan banyak meriwayatkan hadis tentang mandi dan solat baginda. Aisyah berkata Maimunah antara yang paling bertakwa dan paling menjaga silaturahim. Beliau wafat dan dikebumikan di Sarif, di tempat yang sama beliau dinikahkan.",
 en:"The Prophet ﷺ married her at Sarif near Makkah after the Umrah of Qada' in 7 AH. She was the aunt of Ibn Abbas and Khalid ibn al-Walid, and narrated many hadith about his bathing and prayer. Aisha said Maimunah was among the most God-fearing and best at keeping family ties. She died and was buried at Sarif, where she had been married.",
 src:"Sahih Muslim 1411; Sahih al-Bukhari 249"}
];

